def autoregressive_generate(prob_table, prompt, max_new_tokens):
    context = prompt
    for _ in range(max_new_tokens):
        if context not in prob_table:
            break
        dist = prob_table[context]
        if not dist:
            break
        token = max(dist, key=dist.get)
        context += token
    return context


