def build_context(history, new_query, max_tokens):
    def n_tokens(s):
        return len(s.split())

    if n_tokens(new_query) > max_tokens:
        return new_query

    budget = max_tokens - n_tokens(new_query)
    kept = []
    for item in reversed(history):
        cost = n_tokens(item)
        if cost <= budget:
            kept.append(item)
            budget -= cost
        else:
            break
    kept.reverse()
    kept.append(new_query)
    return "\n".join(kept)


if __name__ == "__main__":
    h = ["a b c", "d e", "f g h i"]
    print(repr(build_context(h, "q1 q2", 6)))

