def bpe_merge_once(tokens):
    from collections import Counter
    pairs = Counter(zip(tokens, tokens[1:]))
    if not pairs:
        return (None, 0)
    best = max(pairs.items(), key=lambda kv: (kv[1], [-ord(c) for c in kv[0]]))
    # 并列时取字典序较小：用排序更直观
    best_pair = min(pairs.items(), key=lambda kv: (-kv[1], kv[0]))[0]
    return (best_pair, pairs[best_pair])

