def validate(raw):
    try:
        data = json.loads(raw)
    except Exception as e:
        return False, f"JSON 解析失败: {e}"
    if not isinstance(data, dict):
        return False, "顶层必须是对象"
    s = data.get("sentiment")
    if s not in ("positive", "negative", "neutral"):
        return False, "sentiment 取值非法"
    c = data.get("confidence")
    if not isinstance(c, (int, float)) or isinstance(c, bool):
        return False, "confidence 必须是数值"
    if not 0.0 <= c <= 1.0:
        return False, "confidence 超出 0.0-1.0"
    ev = data.get("evidence")
    if not isinstance(ev, list) or not all(isinstance(x, str) for x in ev):
