import re

ACTION_RE = re.compile(r"Action:\s*(\w+)\[(.*)\]")

def react_loop(question, llm, tools, max_steps=10):
    context = f"Question: {question}\n"
    for _ in range(max_steps):
        out = llm(context)
        context += out + "\n"
        m = ACTION_RE.search(out)
        if not m:
            return False, "no action parsed"
        name, arg = m.group(1), m.group(2).strip()
        if name == "Finish":
            return True, arg
        if name not in tools:
            context += f"Observation: unknown tool {name}\n"
            continue
        try:
            obs = tools[name](arg)
        except Exception as e:
            obs = f"error: {e}"
        context += f"Observation: {obs}\n"
    return False, "max_steps exceeded"

