from typing import TypedDict
from langgraph.graph import StateGraph, END

MAX_ROUNDS = 3

class State(TypedDict):
    facts: dict
    outline: list
    draft: str
    errors: list
    rounds: int

def explore(state):
    return {"facts": {"name": "demo", "deps": [], "entrypoints": []}}

def outline(state):
    return {"outline": ["Install", "Quickstart", "API", "Config", "Contributing"]}

def draft(state):
    return {"draft": "# demo\n...", "rounds": state.get("rounds", 0) + 1}

def verify(state):
    errors = []  # 真实场景由链接检查/代码块执行给出
    return {"errors": errors}

def should_continue(state):
    if not state.get("errors"):
        return END
    if state.get("rounds", 0) >= MAX_ROUNDS:
        return END
    return "draft"

def build_graph():
    g = StateGraph(State)
    g.add_node("explore", explore)
    g.add_node("outline", outline)
    g.add_node("draft", draft)
    g.add_node("verify", verify)
    g.set_entry_point("explore")
    g.add_edge("explore", "outline")
    g.add_edge("outline", "draft")
    g.add_edge("draft", "verify")
    g.add_conditional_edges("verify", should_continue, {"draft": "draft", END: END})
    return g.compile()

