import hashlib, json

class RepeatGuard:
    def __init__(self, warn_at=2, abort_at=3):
        self.warn_at = warn_at
        self.abort_at = abort_at
        self.seen = {}

    def _hash(self, name, args):
        payload = name + json.dumps(args, sort_keys=True)
        return hashlib.md5(payload.encode()).hexdigest()

    def check(self, name, args):
        h = self._hash(name, args)
        count = self.seen.get(h, 0) + 1
        self.seen[h] = count
        if count >= self.abort_at:
            return 'abort'
        if count >= self.warn_at:
            return 'warn'
        return 'ok'


if __name__ == '__main__':
    g = RepeatGuard()
    a = {'url': 'example.com/pricing'}
    b = {'url': 'example.com/pricing'}
    print(g.check('fetch_url', a))  # ok
    print(g.check('fetch_url', b))  # warn
    print(g.check('fetch_url', a))  # abort
    print(g.check('fetch_url', {'url': 'other.com'}))  # ok

