import hashlib, json

MAX_STEPS = 8
DANGEROUS = {'write_file', 'send_email', 'delete'}

def args_hash(name, args):
    return hashlib.md5((name + json.dumps(args, sort_keys=True)).encode()).hexdigest()

def run_agent(llm_decide, call_tool, ask_human, history):
    seen = {}
    for step in range(MAX_STEPS):
        action = llm_decide(history)
        h = args_hash(action.name, action.args)
        if seen.get(h, 0) >= 2:
            history.append('该调用已重复失败，请更换策略')
            continue
        seen[h] = seen.get(h, 0) + 1

        if action.name in DANGEROUS:
            if not ask_human(action):
                history.append('人工拒绝危险操作，任务终止')
                break

        try:
            result = call_tool(action.name, action.args, timeout=10)
        except TimeoutError:
            history.append(f'{action.name} 调用超时')
            continue
        history.append(result)
    else:
        history.append('达到最大步数，任务终止')
    return history

