class AIAgent:
    def __init__(self, llm, tools, max_steps=10):
        self.llm = llm
        self.tools = tools
        self.memory = []
        self.max_steps = max_steps

    def is_finished(self):
        return bool(self.memory) and self.memory[-1].get("done", False)

    def final_answer(self):
        return self.memory[-1]["observation"] if self.memory else None

    def run(self, task):
        steps = 0
        while not self.is_finished() and steps < self.max_steps:
            thought = self.llm.think(task, self.memory, self.tools)
            action = thought.get_action()
            try:
                observation = self.tools[action.name](action.input)
            except Exception as e:
                observation = f"工具调用失败: {e}"
            self.memory.append({
                "thought": thought,
                "action": action,
                "observation": observation,
            })
            steps += 1
        return self.final_answer()

def select_tool(query, tools):
    best_name, best_score = None, 0
    q = query.lower()
    for t in tools:
        desc = t["description"].lower()
        score = sum(1 for w in q.split() if w and w in desc)
        if score > best_score:
            best_score, best_name = score, t["name"]
    return best_name

