class RetryCircuitBreaker:
    def __init__(self, max_retries, threshold):
        self.max_retries = max_retries
        self.threshold = threshold
        self.failures = 0
        self.open = False

    def call(self, fn):
        if self.open:
            return (None, "degraded")
        for _ in range(self.max_retries):
            try:
                result = fn()
                self.failures = 0
                return (result, "ok")
            except Exception:
                self.failures += 1
                if self.failures >= self.threshold:
                    self.open = True
                    return (None, "degraded")
        return (None, "retry")

if __name__ == "__main__":
    cb = RetryCircuitBreaker(2, 2)
    def bad():
        raise ValueError("boom")
    print(cb.call(bad))
    print(cb.call(bad))
    print(cb.call(lambda: "fine"))

