import time

RETRYABLE = {429, 503, 'timeout'}

REGISTRY = {
    'query_order': {'idempotent': True},
    'create_refund': {'idempotent': False},
}

class ToolError(Exception):
    def __init__(self, code):
        self.code = code

def _invoke(name, params, idempotency_key):
    # 占位：真实实现调用下游服务
    raise ToolError(503)

def call_tool(name, params, idempotency_key=None):
    idempotent = REGISTRY[name]['idempotent']
    max_retries = 3
    for attempt in range(max_retries + 1):
        try:
            return _invoke(name, params, idempotency_key)
        except ToolError as e:
            retryable = e.code in RETRYABLE
            if not retryable or not idempotent or attempt == max_retries:
                raise
            time.sleep(2 ** attempt)

