def estimate_cost(steps, sys_tokens, schema_tokens, per_step_tokens, in_price, out_price):
    total_input = 0
    for n in range(1, steps + 1):
        total_input += sys_tokens + schema_tokens + n * per_step_tokens
    total_output = steps * per_step_tokens
    total_cost = total_input / 1e6 * in_price + total_output / 1e6 * out_price
    return total_input, total_output, total_cost

