def step_efficiency(trace, optimal_steps):
    if optimal_steps <= 0:
        raise ValueError("optimal_steps must be positive")
    return len(trace) / optimal_steps

def repeat_rate(trace):
    if len(trace) < 2:
        return 0.0
    repeats = 0
    for a, b in zip(trace, trace[1:]):
        if a.get("tool") == b.get("tool") and a.get("args") == b.get("args"):
            repeats += 1
    return repeats / (len(trace) - 1)

def hit_max_steps(trace, max_steps):
    return len(trace) >= max_steps

def trajectory_metrics(trace, optimal_steps, max_steps):
    return {
        "step_efficiency": step_efficiency(trace, optimal_steps),
        "repeat_rate": repeat_rate(trace),
        "hit_max_steps": hit_max_steps(trace, max_steps),
    }

