import re

PHONE = re.compile(r'1\d{10}')
EMAIL = re.compile(r'([\w.+-])[\w.+-]*@([\w.-]+)')
SENSITIVE = ('api_key', 'token', 'secret')

def _mask_str(s):
    s = PHONE.sub(lambda m: m.group(0)[:3] + '****' + m.group(0)[-4:], s)
    s = EMAIL.sub(lambda m: m.group(1) + '***@' + m.group(2), s)
    return s

def sanitize_trace(event):
    if isinstance(event, dict):
        out = {}
        for k, v in event.items():
            if any(t in k.lower() for t in SENSITIVE):
                out[k] = '***'
            else:
                out[k] = sanitize_trace(v)
        return out
    if isinstance(event, list):
        return [sanitize_trace(v) for v in event]
    if isinstance(event, str):
        return _mask_str(event)
    return event

