import fnmatch

def _match(pattern, action, path):
    if ':' not in pattern:
        return False
    pat_action, pat_path = pattern.split(':', 1)
    if pat_action != action:
        return False
    return fnmatch.fnmatchcase(path, pat_path)

def check_permission(action, path, config):
    for pattern in config.get('deny', []):
        if _match(pattern, action, path):
            return False
    for pattern in config.get('allow', []):
        if _match(pattern, action, path):
            return True
    return False

