def parse_ts(s, local_tz):
    s = s.strip()
    if s.endswith('Z'):
        dt = datetime.strptime(s[:-1], '%Y-%m-%d %H:%M:%S')
        return dt.replace(tzinfo=timezone.utc)
    dt = datetime.strptime(s, '%Y-%m-%d %H:%M:%S')
    return dt.replace(tzinfo=local_tz)

