def build_context(docs, max_chars):
    seen = set()
    parts = []
    total = 0
    for doc in docs:
        if doc in seen:
            continue
        seen.add(doc)
        extra = len(doc) if not parts else len(doc) + 1
        if total + extra > max_chars:
            break
        parts.append(doc)
        total += extra
    return " ".join(parts)

