def rrf_fuse(dense_ids, sparse_ids, alpha=0.5, k=60, top_n=10):
    """RRF 融合两路检索结果，返回 top_n 个文档 id。"""
    scores = {}
    for rank, doc_id in enumerate(dense_ids):
        scores[doc_id] = scores.get(doc_id, 0.0) + alpha * 1.0 / (rank + k)
    for rank, doc_id in enumerate(sparse_ids):
        scores[doc_id] = scores.get(doc_id, 0.0) + (1 - alpha) * 1.0 / (rank + k)
    ranked = sorted(scores.items(), key=lambda x: -x[1])
    return [doc_id for doc_id, _ in ranked[:top_n]]


if __name__ == "__main__":
    print(rrf_fuse(["a", "b", "c"], ["b", "a", "d"], alpha=0.5, top_n=3))

def bm25_score(query_terms, doc_tf, doc_len, avg_dl, idf, k1=1.6, b=0.75):
    """计算查询对单个文档的 BM25 得分。"""
    score = 0.0
    for term in query_terms:
        tf = doc_tf.get(term, 0)
        if tf == 0:
            continue
        denom = tf + k1 * (1 - b + b * doc_len / avg_dl)
        score += idf.get(term, 0.0) * tf * (k1 + 1) / denom
    return score


if __name__ == "__main__":
    print(bm25_score(["rag", "检索"], {"rag": 3, "检索": 1}, 100, 120, {"rag": 2.0, "检索": 1.5}))

