from collections import deque


def has_path(graph, start, end, max_hops):
    if start == end:
        return True
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        node, depth = queue.popleft()
        if depth >= max_hops:
            continue
        for nxt in graph.get(node, []):
            if nxt == end:
                return True
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, depth + 1))
    return False


if __name__ == "__main__":
    g = {"A": ["B"], "B": ["C"], "C": ["D"], "D": []}
    print(has_path(g, "A", "D", 3))
    print(has_path(g, "A", "D", 2))

