def _normalize(text):
    return ''.join(text.lower().split())


def _ngrams(text, n=3):
    text = _normalize(text)
    if len(text) < n:
        return {text} if text else set()
    return {text[i:i + n] for i in range(len(text) - n + 1)}


def _jaccard(a, b):
    if not a and not b:
        return 1.0
    if not a or not b:
        return 0.0
    return len(a & b) / len(a | b)


def build_eval_set(train_texts, eval_texts, threshold=0.95):
    train_grams = [_ngrams(t) for t in train_texts]
    kept = []
    for cand in eval_texts:
        cand_grams = _ngrams(cand)
        duplicated = any(
            _jaccard(cand_grams, tg) > threshold for tg in train_grams
        )
        if not duplicated:
            kept.append(cand)
    return kept


