class BlockManager:
    def __init__(self, block_size=16):
        self.block_size = block_size
        self.seq_tokens = {}

    def append(self, seq_id, n_tokens):
        self.seq_tokens[seq_id] = self.seq_tokens.get(seq_id, 0) + n_tokens
        return self._blocks_of(self.seq_tokens[seq_id])

    def _blocks_of(self, n):
        return (n + self.block_size - 1) // self.block_size

    def used_blocks(self):
        return sum(self._blocks_of(n) for n in self.seq_tokens.values())


