def schedule(requests, max_slots):
    finish = {}
    queue = list(requests)
    running = []   # [(req_id, remaining)]
    step = 0
    while queue or running:
        step += 1
        # 先补充空槽位
        while queue and len(running) < max_slots:
            rid, need = queue.pop(0)
            running.append([rid, need])
        # 所有运行中的请求各推进 1 个 step
        still = []
        for rid, rem in running:
            rem -= 1
            if rem == 0:
                finish[rid] = step
            else:
                still.append([rid, rem])
        running = still
    return finish, step


if __name__ == "__main__":
    reqs = [("A", 3), ("B", 1), ("C", 1), ("D", 2)]
    print(schedule(reqs, max_slots=2))
    # B 在 step1 完成，C 在 step2 补位完成，A 在 step3 完成，D 在 step4 完成

