def plan_concurrency(kv_pool_tokens, max_model_len, max_num_seqs):
    if max_model_len <= 0 or max_num_seqs <= 0:
        return 0, 'reject'
    theoretical = kv_pool_tokens // max_model_len
    concurrency = min(theoretical, max_num_seqs)
    if concurrency == 0:
        return 0, 'reject'
    if theoretical < max_num_seqs:
        return concurrency, 'shrink_len'
    return concurrency, 'ok'


