import math


def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na * nb)


def semantic_cache_lookup(query_vec, cache, threshold):
    best_answer, best_score = None, -1.0
    for vec, answer in cache:
        score = cosine(query_vec, vec)
        if score > best_score:
            best_score, best_answer = score, answer
    if best_answer is not None and best_score >= threshold:
        return best_answer
    return None


