import time

def call_with_retry(fn, max_retries=3, base_delay=0.5, sleep=time.sleep):
    last_exc = None
    for attempt in range(max_retries + 1):
        try:
            return fn()
        except Exception as e:
            last_exc = e
            if attempt == max_retries:
                break
            delay = base_delay * (2 ** attempt) + random.uniform(0, base_delay)
            sleep(delay)
    raise last_exc

