def _norm(pairs):
    if not pairs:
        return {}
    scores = [s for _, s in pairs]
    lo, hi = min(scores), max(scores)
    if hi == lo:
        return {d: 1.0 for d, _ in pairs}
    return {d: (s - lo) / (hi - lo) for d, s in pairs}


def hybrid_merge(dense, sparse, alpha=0.5, top_k=5):
    dn, sn = _norm(dense), _norm(sparse)
    ids = set(dn) | set(sn)
    merged = {i: alpha * dn.get(i, 0.0) + (1 - alpha) * sn.get(i, 0.0) for i in ids}
    ranked = sorted(merged.items(), key=lambda x: x[1], reverse=True)
    return [i for i, _ in ranked[:top_k]]


