def plan_layers(tools, deps):
    indeg = {t: 0 for t in tools}
    children = {t: [] for t in tools}
    for t in tools:
        for pre in deps.get(t, []):
            indeg[t] += 1
            children[pre].append(t)
    layers = []
    ready = sorted(t for t in tools if indeg[t] == 0)
    done = 0
    while ready:
        layers.append(ready)
        nxt = []
        for t in ready:
            done += 1
            for c in children[t]:
                indeg[c] -= 1
                if indeg[c] == 0:
                    nxt.append(c)
        ready = sorted(nxt)
    return layers if done == len(tools) else []

from concurrent.futures import ThreadPoolExecutor, TimeoutError

def run_with_retry(func, retries=2, timeout=1.0):
    last = None
    with ThreadPoolExecutor(max_workers=1) as ex:
        for _ in range(retries + 1):
            try:
                return ex.submit(func).result(timeout=timeout)
            except TimeoutError as e:
                last = e
            except Exception as e:
                last = e
    raise last

def evaluate(predictions, golds):
    if not predictions or not golds:
        return {"accuracy": 0.0, "f1": 0.0}
    assert len(predictions) == len(golds)

    correct = sum(1 for p, g in zip(predictions, golds) if p == g)
    accuracy = correct / len(golds)

    tp = fp = fn = 0
    for p, g in zip(predictions, golds):
        p_tokens = p.split()
        g_tokens = g.split()
        g_set = list(g_tokens)
        for t in p_tokens:
            if t in g_set:
                tp += 1
                g_set.remove(t)
            else:
                fp += 1
        fn += len(g_set)

    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    return {"accuracy": accuracy, "f1": f1}

