        return []
    total = min(total or len(cases), len(cases))

    buckets = {k: [] for k in RATIOS}
    for c in cases:
        buckets.setdefault(c["type"], []).append(c)

    targets = {k: int(round(total * r)) for k, r in RATIOS.items()}
    picked, remaining = {}, total
    for k in RATIOS:
        take = min(targets[k], len(buckets.get(k, [])))
        picked[k] = take
        remaining -= take

    while remaining > 0:
        pool = [k for k in RATIOS if picked[k] < len(buckets.get(k, []))]
        if not pool:
            break
        for k in pool:
            if remaining == 0:
                break
            picked[k] += 1
            remaining -= 1

    result = []
    for k in RATIOS:
        items = buckets.get(k, [])[:]
        random.shuffle(items)
        result.extend(items[:picked[k]])
    return result

