def estimate_saving(prefix_tokens, dynamic_tokens, calls, price_per_token, hit_rate):
    no_cache = (prefix_tokens + dynamic_tokens) * price_per_token * calls
    with_cache = 0.0
    for _ in range(calls):
        if hit_rate > 0:
            # 命中时前缀不计费，仅动态输入计费
            cost = dynamic_tokens * price_per_token
        else:
            cost = (prefix_tokens + dynamic_tokens) * price_per_token
        with_cache += cost
    return no_cache - with_cache


