solution:
def bleu_1(candidate, reference):
    cand = candidate.lower().split()
    ref = reference.lower().split()
    if not cand:
        return 0.0
    ref_count = {}
    for w in ref:
        ref_count[w] = ref_count.get(w, 0) + 1
    hit = 0
    for w in cand:
        if ref_count.get(w, 0) > 0:
            hit += 1
            ref_count[w] -= 1
    return hit / len(cand)


def rouge_l(candidate, reference):
    cand = candidate.lower().split()
    ref = reference.lower().split()
    if not ref:
        return 0.0
    m, n = len(cand), len(ref)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if cand[i - 1] == ref[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n] / n


if __name__ == '__main__':
    print(bleu_1('the cat sat', 'the cat is on the mat'))
    print(rouge_l('the cat sat', 'the cat is on the mat'))

