import math

def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na * nb)

def build_index(docs, centroids):
    buckets = {i: [] for i in range(len(centroids))}
    for text, vec in docs:
        best = max(range(len(centroids)), key=lambda i: cosine(vec, centroids[i]))
        buckets[best].append((text, vec))
    return buckets

def search(query, buckets, centroids, nprobe, k):
    order = sorted(range(len(centroids)),
                   key=lambda i: cosine(query, centroids[i]), reverse=True)
    cand = []
    for i in order[:nprobe]:
        cand.extend(buckets.get(i, []))
    scored = [(text, cosine(query, vec)) for text, vec in cand]
    scored.sort(key=lambda x: x[1], reverse=True)
    return scored[:k]

