def resilience(results):
    grouped = {}
    for r in results:
        level = str(r.get("level"))
        g = grouped.setdefault(level, {"count": 0, "blocked": 0})
        g["count"] += 1
        if not r.get("bypassed"):
            g["blocked"] += 1
    out = {}
    for level, g in grouped.items():
        out[level] = {
            "count": g["count"],
            "resilience": round(g["blocked"] / g["count"] * 100, 2),
        }
    return out

